std::uint32_t hash(const timeline::Surface& s){std::uint32_t h=2166136261;for(auto p:s.pixels)for(int n=0;n<4;++n){h^=(p>>(8*n))&255;h*=16777619;}return h;}
Document fixture(bool linked,int active){
 timeline::State state;state.layers={{"layer",U"Resource"}};auto& l=state.layers.front();l.kind="free-tile";state.frames={{"f0",100},{"f1",137,true}};auto set=tiles::blankTileset("set",U"Source",2,3,"tile",1);tiles::writeTile(set,"tile",{0xff0000ff,0x8000ff00,0xffff0000,0x004d5863,0xff634221,0x7f030201});state.tilesets={set};free_tiles::LayerData data;data.setId="free";free_tiles::Source src;src.id="source";src.name="Source";src.tilesetId="set";src.offsetX=-1;src.offsetY=1;data.sources={src};l.freeTiles=data;
 timeline::Cel c;c.id="c0";c.layerId=l.id;c.frameId="f0";c.opacity=1;c.freeTiles=free_tiles::CelData{};const int xs[]{-3,-1,0,3,6};for(int i=0;i<5;++i){free_tiles::Instance v;v.id="i"+std::to_string(i);v.sourceId="source";v.x=xs[i];v.y=i%3-1;v.rotation=i%4;v.flipHorizontal=i%2==0;v.visible=i!=2;v.locked=i==4;c.freeTiles->instances.push_back(v);}timeline::Surface s;s.width=6;s.height=4;s.offsetX=-1;s.offsetY=1;s.pixels=free_tiles::render(data,*c.freeTiles,state.tilesets,6,4);c.surface=s;auto second=c;second.id="c1";second.frameId="f1";second.surface->offsetX=1;second.surface->offsetY=-2;if(linked)second.linkedCelId="c0";state.cels={c,second};Document base(6,4);auto encoded=project::encodeEditableProject(base);return Document::fromImported(6,4,std::move(state),base.palette(),encoded.projectId,U"Resize",encoded.bytes,active?"f1":"f0");
}
void compare(const Document& d,const std::vector<TileImageSurfaceOracle>& expected){for(int n=0;n<2;++n){const auto r=d.timeline().resolveSurface("c"+std::to_string(n));CHECK(r.surface&&r.source&&r.source->freeTiles);const auto& s=*r.surface;const auto& e=expected[n];CHECK(s.width==e.width&&s.height==e.height&&s.offsetX==e.x&&s.offsetY==e.y&&hash(s)==e.hash);std::vector<int> positions;for(const auto& i:r.source->freeTiles->instances){positions.push_back(i.x);positions.push_back(i.y);const int n=std::stoi(i.id.substr(1));CHECK(i.rotation==n%4&&i.flipHorizontal==(n%2==0)&&i.visible==(n!=2)&&i.locked==(n==4));}CHECK(positions==e.positions);}}
void reopen(Document& d,const std::filesystem::path& path,const std::vector<TileImageSurfaceOracle>& expected){const auto before=d.timeline().state();project::saveDocumentAtomic(d,path);std::ifstream in(path,std::ios::binary);auto bytes=std::make_shared<const project::Bytes>(std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>());auto loaded=project::createEditableDocument(project::prepareEditableImport(project::readProjectManifest(bytes)));compare(loaded,expected);CHECK(loaded.width()==d.width()&&loaded.height()==d.height()&&loaded.timeline().state().tilesets[0].pixels==before.tilesets[0].pixels&&loaded.timeline().state().layers[0].freeTiles==before.layers[0].freeTiles);CHECK(loaded.timeline().findCelById("c1")->linkedCelId==d.timeline().findCelById("c1")->linkedCelId);}
Document gridFixture(bool linked,int active,bool mixed=false){auto base=fixture(linked,active);auto state=base.timeline().state();state.layers[0].kind="tilemap";state.layers[0].tilemapTilesetId="set";state.layers[0].freeTiles.reset();for(auto& c:state.cels){c.freeTiles.reset();c.tilemap=tiles::CelData{2,3,3,2,{}};for(int i=0;i<6;++i)c.tilemap->cells.push_back(i==1?std::optional<tiles::Cell>{}:tiles::Cell{"set","tile",i%2==0,i==3,i%4});c.surface->width=6;c.surface->height=6;c.surface->pixels=tiles::render(*c.tilemap,state.tilesets);}
 if(mixed){timeline::Layer l;l.id="plain";l.name=U"Hidden locked";l.visible=false;l.locked=true;state.layers.push_back(l);for(int i=0;i<2;++i){timeline::Cel c;c.id="p"+std::to_string(i);c.layerId="plain";c.frameId=state.frames[i].id;timeline::Surface s;s.width=2;s.height=1;s.offsetX=-1;s.offsetY=1;s.storageOriginX=17;s.pixels={0x00123456,0xffabcdef};c.surface=s;if(i)c.linkedCelId="p0";state.cels.push_back(c);timeline::MaskSlot m;m.ownerId="layer";m.frameId=c.frameId;m.mask.id="m"+std::to_string(i);m.mask.surface=s;m.mask.surface.pixels={0xff000000,0xffffffff};if(i)m.mask.linkedMaskId="m0";state.masks.push_back(m);}}
 auto encoded=project::encodeEditableProject(Document(6,4));return Document::fromImported(6,4,std::move(state),base.palette(),encoded.projectId,U"Grid resize",encoded.bytes,active?"f1":"f0");}
void gridRoundtrip(Document& d,const std::filesystem::path& path){const auto before=d.timeline().state();project::saveDocumentAtomic(d,path);std::ifstream in(path,std::ios::binary);auto bytes=std::make_shared<const project::Bytes>(std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>());auto loaded=project::createEditableDocument(project::prepareEditableImport(project::readProjectManifest(bytes)));CHECK(loaded.width()==d.width()&&loaded.height()==d.height());const auto& after=loaded.timeline().state();CHECK(after.tilesets[0].tileWidth==before.tilesets[0].tileWidth&&after.tilesets[0].tileHeight==before.tilesets[0].tileHeight&&after.tilesets[0].pixels==before.tilesets[0].pixels);for(const auto& c:before.cels){const auto a=d.timeline().resolveSurface(c.id),b=loaded.timeline().resolveSurface(c.id);CHECK(a.surface->width==b.surface->width&&a.surface->height==b.surface->height&&a.surface->offsetX==b.surface->offsetX&&a.surface->offsetY==b.surface->offsetY&&a.surface->pixels==b.surface->pixels);if(a.source->tilemap)CHECK(a.source->tilemap->cells==b.source->tilemap->cells&&a.source->tilemap->tileWidth==b.source->tilemap->tileWidth&&a.source->tilemap->tileHeight==b.source->tilemap->tileHeight);}}
void verifyGrid(const std::filesystem::path& directory){int n=0;for(bool linked:{false,true})for(int active:{0,1})for(bool smooth:{false,true}){auto d=gridFixture(linked,active,true);const auto before=d.timeline().state();gridRoundtrip(d,directory/("grid-source-"+std::to_string(n)+".moonsprite"));const auto activeFrame=d.frame().id;d.previewSelection(SelectionMask{0,0,3,2,{1,0,1,0,1,0}});CHECK(d.selectAttachedMask("layer",activeFrame));const auto mask=d.activeMaskId();const auto history=d.historyPosition();CHECK(d.resizeImage(smooth?9:12,smooth?7:8,smooth?ImageInterpolation::Smooth:ImageInterpolation::Nearest));CHECK(d.historyPosition()==history+1&&d.frame().id==activeFrame&&d.activeMaskId()==mask);const auto& after=d.timeline().state();CHECK(after.layers[1].locked&&!after.layers[1].visible&&after.masks[1].mask.linkedMaskId=="m0");CHECK(after.cels[0].tilemap->cells==before.cels[0].tilemap->cells&&after.cels[0].tilemap->columns==3&&after.cels[0].tilemap->rows==2);const auto& set=after.tilesets[0];CHECK(set.id=="set"&&set.tileIds==before.tilesets[0].tileIds&&set.tileSlots==before.tilesets[0].tileSlots&&set.tileWidth==(smooth?3:4)&&set.tileHeight==(smooth?5:6));if(!smooth)for(int y=0;y<6;++y)for(int x=0;x<4;++x)CHECK(set.pixels[y*4+x]==before.tilesets[0].pixels[(y/2)*2+x/2]);const auto surface=*d.timeline().resolveSurface("c0").surface;CHECK(surface.width==(smooth?9:12)&&surface.height==(smooth?10:12)&&surface.offsetX==-2&&surface.offsetY==(smooth?1:2));const auto resizedPixels=surface.pixels;gridRoundtrip(d,directory/("grid-output-"+std::to_string(n)+".moonsprite"));d.undo();CHECK(d.width()==6&&d.height()==4&&d.activeMaskId()==mask&&d.timeline().state().tilesets[0].pixels==before.tilesets[0].pixels&&d.timeline().state().masks[0].mask.surface.width==2);d.redo();CHECK(d.timeline().resolveSurface("c0").surface->pixels==resizedPixels);++n;}}
void verify(const std::filesystem::path& directory){std::filesystem::create_directories(directory);int index=0;for(const auto& o:tileImageOracle){try{auto d=fixture(o.linked,o.active);compare(d,o.before);reopen(d,directory/("source-"+std::to_string(index)+".moonsprite"),o.before);const auto h=d.historyPosition(),r=d.contentRevision(),id=d.identity();const auto active=d.frame().id;d.previewSelection(SelectionMask{0,0,3,2,{1,0,1,0,1,0}});CHECK(d.resizeImage(o.width,o.height,o.smooth?ImageInterpolation::Smooth:ImageInterpolation::Nearest));CHECK(d.identity()==id&&d.contentRevision()>r&&d.historyPosition()==h+1&&d.frame().id==active);compare(d,o.after);const auto& set=d.timeline().state().tilesets[0];CHECK(set.tileWidth==o.tileWidth&&set.tileHeight==o.tileHeight&&set.pixels==o.pixels&&set.id=="set"&&set.tileIds==std::vector<std::string>{"tile"});const auto& source=d.timeline().state().layers[0].freeTiles->sources[0];CHECK(source.offsetX==o.sourceX&&source.offsetY==o.sourceY);d.undo();compare(d,o.before);CHECK(d.width()==6&&d.height()==4&&d.selection()->mask==std::vector<unsigned char>({1,0,1,0,1,0}));d.redo();compare(d,o.after);reopen(d,directory/("output-"+std::to_string(index)+".moonsprite"),o.after);++index;}catch(const std::exception& e){throw std::runtime_error("Legacy image case "+std::to_string(index)+": "+e.what());}}
 verifyGrid(directory);for(const auto& o:tileImageOracle)if(o.linked){auto source=fixture(true,o.active);auto state=source.timeline().state();state.cels[1].linkedCelId.reset();state.cels[1].runtimeSharedCelId="c0";auto encoded=project::encodeEditableProject(Document(6,4));auto shared=Document::fromImported(6,4,std::move(state),source.palette(),encoded.projectId,U"Shared resize",encoded.bytes,o.active?"f1":"f0");CHECK(shared.resizeImage(o.width,o.height,o.smooth?ImageInterpolation::Smooth:ImageInterpolation::Nearest));compare(shared,o.after);CHECK(shared.timeline().findCelById("c1")->runtimeSharedCelId==std::optional<std::string>{"c0"});shared.undo();compare(shared,o.before);}
 auto d=fixture(false,0);const auto h=d.historyPosition(),r=d.revision();bool rejected=false;try{d.resizeImage(8192,8192);}catch(const std::exception&){rejected=true;}CHECK(rejected&&d.width()==6&&d.historyPosition()==h&&d.revision()==r);CHECK(resizeFreeTileImagePixels({0x000000ff,0xff000000},2,1,3,1,ImageInterpolation::Smooth)==std::vector<Pixel>({0,0x80000000,0xff000000}));std::cout<<index<<" actual legacy image resizes, source/output reopens, Undo/Redo and failure guards passed\n";}
int wmain(int argc,wchar_t** argv){try{verify(argc>1?std::filesystem::path(argv[1]):std::filesystem::path(L"tile-image-owned"));return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
